import { ARCHIVOS_MARCA, MARCA } from "./identidad";

interface Props {
  /** Only the hedge-and-stall symbol, for round buttons and tight spots. */
  soloSimbolo?: boolean;
  alto?: number;
  /** Next to a label that already names it (an aria-label), the image stays silent. */
  decorativa?: boolean;
}

/** The Hedge Parking logo from public/brand, generated by brand/generar.py. */
export function Marca({ soloSimbolo = false, alto = 32, decorativa = false }: Props) {
  return (
    <img
      className="ui-marca"
      src={soloSimbolo ? ARCHIVOS_MARCA.simbolo : ARCHIVOS_MARCA.lockup}
      alt={decorativa ? "" : MARCA}
      height={alto}
    />
  );
}
